import itertools
import json

def solve_puzzle():
    # Houses
    houses = [1, 2]

    # Attributes and their possible values
    categories = {
        "name": ["Eric", "Arnold"],
        "hobby": ["gardening", "photography"],
        "type of pet": ["cat", "dog"],
        "heights": ["short", "very short"],
    }

    # Helper to create position lookups
    def positions(mapping):
        # mapping: dict of category -> tuple assigned per house index (0-based)
        pos = {}
        for cat, vals in mapping.items():
            pos[cat] = {}
            for idx, val in enumerate(vals):
                pos[cat][val] = idx + 1  # house numbers start at 1
        return pos

    solutions = []

    # Iterate over all permutations for each category
    for names_perm in itertools.permutations(categories["name"]):
        # Constraint 2: Eric is the person who is very short.
        # We will check this after assigning heights.
        for heights_perm in itertools.permutations(categories["heights"]):
            # Early prune using Constraint 2:
            # Find positions
            pos_names = {val: i + 1 for i, val in enumerate(names_perm)}
            pos_heights = {val: i + 1 for i, val in enumerate(heights_perm)}
            if pos_names["Eric"] != pos_heights["very short"]:
                continue

            for hobbies_perm in itertools.permutations(categories["hobby"]):
                # Constraint 1: The person who is very short is the photography enthusiast.
                pos_hobbies = {val: i + 1 for i, val in enumerate(hobbies_perm)}
                if pos_heights["very short"] != pos_hobbies["photography"]:
                    continue

                for pets_perm in itertools.permutations(categories["type of pet"]):
                    pos_pets = {val: i + 1 for i, val in enumerate(pets_perm)}

                    # Constraint 3: The person who has a cat is somewhere to the right of the person who is very short.
                    if not (pos_pets["cat"] > pos_heights["very short"]):
                        continue

                    # All constraints satisfied; record solution
                    mapping = {
                        "name": names_perm,
                        "hobby": hobbies_perm,
                        "type of pet": pets_perm,
                        "heights": heights_perm,
                    }
                    solutions.append(mapping)

    if len(solutions) != 1:
        raise RuntimeError(f"Expected exactly one solution, found {len(solutions)}")

    sol = solutions[0]

    header = ["House", "name", "hobby", "type of pet", "heights"]
    rows = []
    for i, house in enumerate(houses):
        row = [
            str(house),
            sol["name"][i],
            sol["hobby"][i],
            sol["type of pet"][i],
            sol["heights"][i],
        ]
        rows.append(row)

    output = {
        "solution": {
            "header": header,
            "rows": rows,
        }
    }
    print(json.dumps(output, ensure_ascii=False))


if __name__ == "__main__":
    solve_puzzle()
